// Interactive, projected 3D engineering wireframe.
const stage=document.querySelector('.crane-stage');
const modelCanvas=document.createElement('canvas');modelCanvas.className='crane-model';modelCanvas.setAttribute('aria-label','Interactive three-dimensional crane blueprint');stage.prepend(modelCanvas);
const modelContext=modelCanvas.getContext('2d');const segments=[];
const edge=(a,b,c='#e8732f',alpha=.8)=>segments.push({a,b,c,alpha});
function box(x,y,z,w,h,d){const p=[[x,y,z],[x+w,y,z],[x+w,y+h,z],[x,y+h,z],[x,y,z+d],[x+w,y,z+d],[x+w,y+h,z+d],[x,y+h,z+d]];[[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]].forEach(([a,b])=>edge(p[a],p[b]));}
box(-.8,.12,-.9,2,.42,.45);box(-.8,.12,.48,2,.42,.45);box(-.55,.54,-.62,1.7,.28,1.24);box(-.25,.82,-.53,1.2,.7,1.06);box(-.75,.85,-.58,.53,.66,.55);box(.8,.86,-.5,.6,.4,1);
for(let side of [-.92,.95])for(let x=-.58;x<1.1;x+=.31){let prev;for(let i=0;i<=16;i++){const t=i/16*Math.PI*2;const p=[x+Math.cos(t)*.16,.32+Math.sin(t)*.16,side];if(prev)edge(prev,p,'#a1a7ac',.65);prev=p}}
const boomStart=[-.15,1.35,0],boomEnd=[-2.3,5.65,0];const corners=[[-.13,-.1,-.16],[.13,.1,-.16],[-.13,-.1,.16],[.13,.1,.16]];const at=(t,c)=>boomStart.map((v,i)=>v+(boomEnd[i]-v)*t+corners[c][i]);for(let c=0;c<4;c++){edge(at(0,c),at(1,c),'#ff8d40',1);for(let i=0;i<16;i++){edge(at(i/16,c),at((i+1)/16,(c+1)%4),'#df681e',.65);edge(at(i/16,c),at(i/16,(c+1)%4),'#ffaa66',.5)}}edge([.9,1.4,0],[.45,2.3,0]);edge([.45,2.3,0],boomEnd,'#a3a8ae',.8);edge([.45,2.3,0],[-.2,1.5,0],'#a3a8ae',.6);edge(boomEnd,[-2.3,2.4,0],'#cccccc',.8);edge([-2.34,5.62,0],[-2.34,2.4,0],'#cccccc',.6);edge([-2.3,2.4,0],[-2.8,2.05,0]);edge([-2.3,2.4,0],[-1.8,2.05,0]);box(-3.2,1.86,-.18,1.85,.19,.36);
for(let i=-5;i<=5;i++){edge([i,-.06,-5],[i,-.06,5],'#6e757d',.13);edge([-5,-.06,i],[5,-.06,i],'#6e757d',.13)}
let yaw=-.45,pitch=.08,targetYaw=yaw,targetPitch=pitch;let mw,mh;function modelSize(){const r=stage.getBoundingClientRect();mw=r.width;mh=r.height;const d=Math.min(devicePixelRatio,2);modelCanvas.width=mw*d;modelCanvas.height=mh*d;modelContext.setTransform(d,0,0,d,0,0)}modelSize();addEventListener('resize',modelSize);stage.addEventListener('pointermove',e=>{if(reduce.matches)return;const r=stage.getBoundingClientRect();targetYaw=-.45+(e.clientX-r.left-r.width/2)/r.width*.8;targetPitch=.08+(e.clientY-r.top-r.height/2)/r.height*.15});stage.addEventListener('pointerleave',()=>{targetYaw=-.45;targetPitch=.08});
function project(p){const x=p[0]+.9,y=p[1]-2.6,z=p[2];const rx=x*Math.cos(yaw)-z*Math.sin(yaw),rz=x*Math.sin(yaw)+z*Math.cos(yaw);const ry=y*Math.cos(pitch)-rz*Math.sin(pitch),depth=y*Math.sin(pitch)+rz*Math.cos(pitch);const scale=Math.min(mw/5.9,mh/6.8)*8/(8+depth);return [mw*.5+rx*scale,mh*.52-ry*scale]}
function renderModel(){yaw+=(targetYaw-yaw)*.045;pitch+=(targetPitch-pitch)*.045;modelContext.clearRect(0,0,mw,mh);for(const s of segments){const a=project(s.a),b=project(s.b);modelContext.strokeStyle=s.c;modelContext.globalAlpha=s.alpha;modelContext.lineWidth=s.c==='#ff8d40'?1.5:.8;modelContext.beginPath();modelContext.moveTo(...a);modelContext.lineTo(...b);modelContext.stroke()}requestAnimationFrame(renderModel)}renderModel();
const rotateButton=document.createElement('button');rotateButton.className='blueprint-toggle';rotateButton.textContent='ROTATE 3D VIEW ↻';rotateButton.onclick=()=>{targetYaw+=.35;};stage.append(rotateButton);